package com.example.phishsim;import java.io.Serializable;import java.util.*;
public class TrainingState implements Serializable{private static final long serialVersionUID=1L;private final Map<Integer,Boolean>a=new HashMap<>();private int totalAnswered,correct;public Map<Integer,Boolean>getAnsweredCorrectly(){return a;}public int getTotalAnswered(){return totalAnswered;}public int getCorrect(){return correct;}public int getAccuracyPercentage(){return totalAnswered==0?0:correct*100/totalAnswered;}public void recordAnswer(int id,boolean ok){if(a.containsKey(id)){if(a.get(id))correct--;}else totalAnswered++;a.put(id,ok);if(ok)correct++;}public void reset(){a.clear();totalAnswered=correct=0;}}
